head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.ssMarket = "N"; // 시장 콤보 초기 세팅 완료 여부(초기 setValue 시 onchange 재조회 방지)
scwin.skw = ""; // 회사명 필터 키워드
scwin.stat = ""; // 상장구분 코드
scwin.gListStatCd = ""; // 부모 화면이 지정한 상장구분(지정 시 콤보 고정)
scwin.tpcd = ""; // 세션의 시장구분 (onpageload 에서 취득)

///////// 2. 초기화 영역 /////////
/* ★Wcraft guide★
스크립트 수작업 유의사항

*/
scwin.onpageload = async function () {
    try {
        // 세션 시장구분(js_market) — $c.session.getUserInfo(확정 API). 필드키는 세션 스키마 의존(원본 임시값)
        scwin.tpcd = $c.session.getUserInfo("js_market") ?? "";

        // 구 $c.frame.path("../") — 부모 화면의 상장구분 지정값(규칙 21: getParent)
        scwin.stat = $c.win.getParent()?.js_listStatCd ?? "";
        if (scwin.stat !== "") {
            scwin.gListStatCd = scwin.stat;
            if (scwin.gListStatCd === "Y") {
                combo_stat.setValue("Y");
                combo_stat.setDisabled(true);
            }
        }

        await scwin.code1Sync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDCOM00007.onpageload" });
    }
};

scwin.onpageunload = function () {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
scwin.grd_jongmok_onkeydown = async function (e) {
    try {
        if (Number(e.keyCode) === 13) {
            await scwin.Confirm();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDCOM00007.grd_jongmok_onkeydown" });
    }
};

scwin.grd_jongmok_oncelldblclick = async function (rowIndex, columnIndex, columnId) {
    try {
        await scwin.Confirm();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDCOM00007.grd_jongmok_oncelldblclick" });
    }
};

scwin.img_search_onclick = function (e) {
    try {
        scwin.JongmokSearch();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00007.img_search_onclick" });
    }
};

scwin.txb_jongmokName_onkeydown = function (e) {
    try {
        if (Number(e.keyCode) === 13) {
            scwin.JongmokSearch();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00007.txb_jongmokName_onkeydown" });
    }
};

scwin.combo_market_onselchange = async function (info) {
    try {
        if (scwin.ssMarket === "Y") {
            txb_jongmokName.setValue("");
            scwin.skw = "";
            scwin.tpcd = combo_market.getValue();
            await scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDCOM00007.combo_market_onselchange" });
    }
};

scwin.combo_stat_onselchange = async function (info) {
    try {
        txb_jongmokName.setValue("");
        scwin.skw = "";

        scwin.stat = combo_stat.getValue();
        if (scwin.stat === "0") {
            scwin.stat = "";
        }
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDCOM00007.combo_stat_onselchange" });
    }
};

scwin.btn_ga_onclick = function (e) {
    try {
        scwin.Jongmok('가', '나');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00007.btn_ga_onclick" });
    }
};

scwin.btn_na_onclick = function (e) {
    try {
        scwin.Jongmok('나', '다');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00007.btn_na_onclick" });
    }
};

