        scwin.Jongmok('라', '마');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00007.btn_la_onclick" });
    }
};

scwin.btn_ma_onclick = function (e) {
    try {
        scwin.Jongmok('마', '바');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00007.btn_ma_onclick" });
    }
};

scwin.btn_ba_onclick = function (e) {
    try {
        scwin.Jongmok('바', '사');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00007.btn_ba_onclick" });
    }
};

scwin.btn_sa_onclick = function (e) {
    try {
        scwin.Jongmok('사', '아');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00007.btn_sa_onclick" });
    }
};

scwin.btn_a_onclick = function (e) {
    try {
        scwin.Jongmok('아', '자');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00007.btn_a_onclick" });
    }
};

scwin.btn_ja_onclick = function (e) {
    try {
        scwin.Jongmok('자', '차');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00007.btn_ja_onclick" });
    }
};

scwin.btn_ca_onclick = function (e) {
    try {
        scwin.Jongmok('차', '카');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00007.btn_ca_onclick" });
    }
};

scwin.btn_ka_onclick = function (e) {
    try {
        scwin.Jongmok('카', '타');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00007.btn_ka_onclick" });
    }
};

scwin.btn_ta_onclick = function (e) {
    try {
        scwin.Jongmok('타', '파');
    } catch (ex) {
