        scwin.Jongmok('파', '하');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00007.btn_fa_onclick" });
    }
};

scwin.btn_ha_onclick = function (e) {
    try {
        scwin.Jongmok('하', '豈');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00007.btn_ha_onclick" });
    }
};

scwin.btn_young_onclick = function (e) {
    try {
        scwin.Jongmok('A', 'Z');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00007.btn_young_onclick" });
    }
};

scwin.btn_num_onclick = function (e) {
    try {
        scwin.Jongmok('0', '9');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00007.btn_num_onclick" });
    }
};

// 회사명·이전상호약명 키워드 필터 — 구 Gauce UseFilter/Filter()/OnFilter 대체
scwin.dlt_commonCodecomIsur_OnFilter = function () {
    try {
        dlt_commonCodecomIsur.removeColumnFilterAll();

        if (scwin.skw !== "") {
            dlt_commonCodecomIsur.setColumnFilter({ type : "row", colIndex : "COM_ABBRV", key : scwin.skw, condition : "and", exactMatch : false });
            dlt_commonCodecomIsur.setColumnFilter({ type : "row", colIndex : "OLD_COM_ABBRV", key : scwin.skw, condition : "or", exactMatch : false });
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00007.dlt_commonCodecomIsur_OnFilter" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
// 발행회사 목록 조회 — 조회 후 정렬·필터 반영(구 dts_jongmok_OnLoadCompleted 대체)
scwin.listSync = async function () {
    const sbmOptions = {
        id : "sbm_dlt_commonCodecomIsur",
        action : "/isurcd.do?method=searchIsurCd&LIST_STAT_CD=" + encodeURIComponent(scwin.stat) + "&SPOT_ISU_TRD_MKT_TP_CD=" + encodeURIComponent(scwin.tpcd), // 상장구분·시장구분 필터(원본 ui 확인)
        ref : "",
        target : "dlt_commonCodecomIsur=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
dlt_commonCodecomIsur.sort("COM_ABBRV", 0);
    scwin.dlt_commonCodecomIsur_OnFilter();
    grd_jongmok.setFocusedCell(0, 0);
};

// 시장구분 공통코드 조회 — 조회 후 콤보 세팅·목록 조회(구 MxDataSet_code1_OnLoadCompleted 대체)
scwin.code1Sync = async function () {
    const sbmOptions = {
        id : "sbm_MxDataSet_code1",
        action : "/tbmccdval.do",
        ref : "",
        target : "MxDataSet_code1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);

    scwin.marketSetCombo();
    if (MxDataSet_code1.getRowCount() > 0) {
        await scwin.listSync();
    }
};

///////// 5. 일반/업무 함수 영역 /////////
// 가나다라.. 검색 — 구 countrow/NameValue/Rowposition(Gauce) 대체
scwin.Jongmok = function (prevval, nextval) {
    txb_jongmokName.setValue("");
    scwin.skw = "";
    scwin.dlt_commonCodecomIsur_OnFilter();
    dlt_commonCodecomIsur.sort("COM_ABBRV", 0);

    let cnt = 0;
    for (let i = 0; i < dlt_commonCodecomIsur.getRowCount(); i++) {
        const name = String(dlt_commonCodecomIsur.getCellData(i, "COM_ABBRV")).substring(0, 1);
        if (name >= prevval && name < nextval) {
            cnt = i;
            break;
        }
    }

    // 구 Rowposition = cnt+11 → cnt (스크롤 확보) 트릭 대체
    grd_jongmok.setFocusedCell(Math.min(cnt + 11, Math.max(dlt_commonCodecomIsur.getRowCount() - 1, 0)), 0);
    grd_jongmok.setFocusedCell(cnt, 0);
    grd_jongmok.setFocus();
};

// 회사명 접두 위치 탐색
scwin.JongmokName = function () {
    dlt_commonCodecomIsur.sort("COM_ABBRV", 0);

    let cnt = 0;
    const txtVal = txb_jongmokName.getValue().toUpperCase();
    const len = txtVal.length;
    for (let i = 0; i < dlt_commonCodecomIsur.getRowCount(); i++) {
        const name = String(dlt_commonCodecomIsur.getCellData(i, "COM_ABBRV")).substring(0, len).toUpperCase();
        if (txtVal <= name) {
            cnt = i;
            break;
        }
    }

    grd_jongmok.setFocusedCell(Math.min(cnt + 11, Math.max(dlt_commonCodecomIsur.getRowCount() - 1, 0)), 0);
    grd_jongmok.setFocusedCell(cnt, 0);
};

// 키워드 필터 검색
scwin.JongmokSearch = function () {
    scwin.skw = txb_jongmokName.getValue().toUpperCase();
    scwin.dlt_commonCodecomIsur_OnFilter();
    grd_jongmok.setFocusedCell(0, 0);
};

// 부모창으로 발행회사 정보 전달 — 구 RowPosition/NameValue(Gauce)·frame.Provider 대체
scwin.Confirm = async function () {
    const row = dlt_commonCodecomIsur.getRowPosition();
    if (row < 0) {
        return;
    }
    const pJongCode = dlt_commonCodecomIsur.getCellData(row, "ISUR_CD");
    const pJongNm = dlt_commonCodecomIsur.getCellData(row, "COM_ABBRV");
    const ldMktTpCd = dlt_commonCodecomIsur.getCellData(row, "SPOT_ISU_TRD_MKT_TP_CD");
    $c.win.getParent()?.isurSearch_Rtn(pJongCode, pJongNm, ldMktTpCd);

    await $c.win.closePopup();
};

// 시장 콤보 초기 세팅 — 구 countrow/NameValue/Index(Gauce) 대체
scwin.marketSetCombo = function () {
    if (scwin.tpcd !== "") {
        combo_market.setValue(scwin.tpcd);
    }
    if (scwin.tpcd === "1" || scwin.tpcd === "2") {
        combo_market.setDisabled(true);
    }
    scwin.ssMarket = "Y";
};
